import * as React from "react";

export type FogIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function FogIcon({ size = 20, ...props }: FogIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="7" r="3"/><path d="M4 13.5h16M6 16.5h12M4 19.5h16"/>
    </svg>
  );
}
